package org.documentknowledge.browserbff.application;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class KnowledgeWireTest {
 private static final KnowledgeWire wire=new KnowledgeWire(value->{try{return java.net.URI.create(value).isAbsolute();}catch(IllegalArgumentException invalid){return false;}});
 private static Map<String,Object> map(Object... fields){var result=new LinkedHashMap<String,Object>();for(int i=0;i<fields.length;i+=2)result.put((String)fields[i],fields[i+1]);return result;}
 private static void structuralNegatives(String name,Object fixture){assertTrue(wire.validate(name,fixture),name);assertFalse(wire.validate(name,null));assertFalse(wire.validate(name,false));if(fixture instanceof Map<?,?> raw){@SuppressWarnings("unchecked") Map<String,Object> value=(Map<String,Object>)raw;var unknown=new LinkedHashMap<>(value);unknown.put("forgedActor", "override");assertFalse(wire.validate(name,unknown));for(String key:value.keySet()){var missing=new LinkedHashMap<>(value);missing.remove(key);assertFalse(wire.validate(name,missing),name+" missing "+key);var wrong=new LinkedHashMap<>(value);wrong.put(key,false);assertFalse(wire.validate(name,wrong),name+" invalid "+key);}}}
 @Test void schemaActorRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("Actor",map("issuer","https://issuer.example","subject","Synthetic"));}
 @Test void schemaKnowledgeActionRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("KnowledgeAction","knowledge.collection.create");}
 @Test void schemaErrorRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("Error",map("code","BAD_REQUEST"));}
 @Test void schemaCollectionReceiptRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CollectionReceipt",map("collectionId","11111111-1111-4111-8111-111111111111","revision",1L));}
 @Test void schemaMembershipReceiptRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("MembershipReceipt",map("collectionId","11111111-1111-4111-8111-111111111111","membershipId","11111111-1111-4111-8111-111111111111","revision",1L));}
 @Test void schemaCollectionMetadataRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CollectionMetadata",map("title","Synthetic","description","Synthetic"));}
 @Test void schemaCreateCollectionRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CreateCollection",map("title","Synthetic","description","Synthetic"));}
 @Test void schemaUpdateCollectionRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("UpdateCollection",map("expectedRevision",1L,"metadata",map("title","Synthetic","description","Synthetic")));}
 @Test void schemaCollectionStatusRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CollectionStatus","ACTIVE");}
 @Test void schemaUpdateStatusRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("UpdateStatus",map("expectedRevision",1L,"status","ACTIVE","reason","Synthetic"));}
 @Test void schemaCollectionRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("Collection",map("collectionId","11111111-1111-4111-8111-111111111111","revision",1L,"metadata",map("title","Synthetic","description","Synthetic"),"status","ACTIVE","membershipRevision",1L,"audiencePolicyRevision",1L,"classificationCeiling","development-restricted","classificationPolicyRevision",1L));}
 @Test void schemaCollectionPageRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CollectionPage",map("items",new ArrayList<>(List.of(map("collectionId","11111111-1111-4111-8111-111111111111","revision",1L,"metadata",map("title","Synthetic","description","Synthetic"),"status","ACTIVE","membershipRevision",1L,"audiencePolicyRevision",1L,"classificationCeiling","development-restricted","classificationPolicyRevision",1L))),"nextCursor","opaque"));}
 @Test void schemaAudienceSelectorRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("AudienceSelector",map("kind","PRINCIPAL","principal",map("issuer","https://issuer.example","subject","Synthetic")));}
 @Test void schemaAudienceEvaluationRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("AudienceEvaluation",map("collectionId","11111111-1111-4111-8111-111111111111","audiencePolicyRevision",1L,"decision","ALLOW"));}
 @Test void schemaEvaluateAudienceRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("EvaluateAudience",map());}
 @Test void schemaAudienceRuleRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("AudienceRule",map("effect","ALLOW","selector",map("kind","PRINCIPAL","principal",map("issuer","https://issuer.example","subject","Synthetic"))));}
 @Test void schemaAudiencePolicyRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("AudiencePolicy",map("collectionId","11111111-1111-4111-8111-111111111111","revision",1L,"classificationCeiling","development-restricted","classificationPolicyRevision",1L,"rules",new ArrayList<>(List.of(map("effect","ALLOW","selector",map("kind","PRINCIPAL","principal",map("issuer","https://issuer.example","subject","Synthetic"))))),"effectiveAt","2026-11-01T00:00:00Z"));}
 @Test void schemaUpdateAudienceRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("UpdateAudience",map("expectedRevision",1L,"rules",new ArrayList<>(List.of(map("effect","ALLOW","selector",map("kind","PRINCIPAL","principal",map("issuer","https://issuer.example","subject","Synthetic"))))),"reason","Synthetic"));}
 @Test void schemaAclRuleRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("AclRule",map("principal",map("issuer","https://issuer.example","subject","Synthetic"),"action","knowledge.collection.create","effect","ALLOW"));}
 @Test void schemaAclRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("Acl",map("collectionId","11111111-1111-4111-8111-111111111111","revision",1L,"rules",new ArrayList<>(List.of(map("principal",map("issuer","https://issuer.example","subject","Synthetic"),"action","knowledge.collection.create","effect","ALLOW")))));}
 @Test void schemaAclChangeEntryRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("AclChangeEntry",map("operation","ADD_ALLOW","principal",map("issuer","https://issuer.example","subject","Synthetic"),"action","knowledge.collection.create"));}
 @Test void schemaUpdateAclRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("UpdateAcl",map("expectedRevision",1L,"mode","RESTRICT","changes",new ArrayList<>(List.of(map("operation","ADD_ALLOW","principal",map("issuer","https://issuer.example","subject","Synthetic"),"action","knowledge.collection.create"))),"reason","Synthetic"));}
 @Test void schemaCreateMembershipRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CreateMembership",map("expectedRevision",1L,"documentId","11111111-1111-4111-8111-111111111111","expectedDocumentRevision",1L,"sharingScope","SELECTED_TENANT","reason","Synthetic"));}
 @Test void schemaUpdateMembershipRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("UpdateMembership",map("expectedRevision",1L,"expectedMembershipRevision",1L,"expectedDocumentRevision",1L,"state","ACTIVE","reason","Synthetic"));}
 @Test void schemaMembershipRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("Membership",map("membershipId","11111111-1111-4111-8111-111111111111","collectionId","11111111-1111-4111-8111-111111111111","documentId","11111111-1111-4111-8111-111111111111","revision",1L,"state","ACTIVE","sharingScope","SELECTED_TENANT","creator",map("issuer","https://issuer.example","subject","Synthetic"),"createdAt","2026-11-01T00:00:00Z","reason","Synthetic"));}
 @Test void schemaMembershipPageRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("MembershipPage",map("items",new ArrayList<>(List.of(map("membershipId","11111111-1111-4111-8111-111111111111","collectionId","11111111-1111-4111-8111-111111111111","documentId","11111111-1111-4111-8111-111111111111","revision",1L,"state","ACTIVE","sharingScope","SELECTED_TENANT","creator",map("issuer","https://issuer.example","subject","Synthetic"),"createdAt","2026-11-01T00:00:00Z","reason","Synthetic"))),"nextCursor","opaque"));}
 @Test void schemaCreatePolicySnapshotRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("CreatePolicySnapshot",map("expectedDocumentRevision",1L));}
 @Test void schemaPolicyDecisionRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("PolicyDecision","COMPATIBLE");}
 @Test void schemaPolicySnapshotRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("PolicySnapshot",map("snapshotToken","aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","documentId","11111111-1111-4111-8111-111111111111","documentRevision",1L,"classificationPolicyRevision",1L,"decision","COMPATIBLE"));}
 @Test void schemaValidatePolicyRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("ValidatePolicy",map("snapshotToken","aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","expectedDocumentRevision",1L));}
 @Test void schemaPolicyValidationRejectsUnknownMissingAndWrongTypedFields(){structuralNegatives("PolicyValidation",map("documentId","11111111-1111-4111-8111-111111111111","decision","COMPATIBLE"));}
 @Test void exactRoutesQueriesAndIdempotencyAreClosed(){String id="11111111-1111-4111-8111-111111111111",root="/api/v1/knowledge/collections";assertEquals(200,wire.request("GET",root,Map.of("limit","50","cursor","opaque"),null,null).status());for(String limit:List.of("0","51","01","-1","1.5","NaN"))assertThrows(BffFailure.class,()->wire.request("GET",root,Map.of("limit",limit),null,null));assertThrows(BffFailure.class,()->wire.request("GET",root,Map.of("target","foreign"),null,null));assertThrows(BffFailure.class,()->wire.request("GET",root,Map.of("cursor",""),null,null));assertThrows(BffFailure.class,()->wire.request("GET",root+"/"+id,Map.of("limit","20"),null,null));assertThrows(BffFailure.class,()->wire.request("POST",root,Map.of(),map("title","Synthetic","description",""),null));assertThrows(BffFailure.class,()->wire.request("GET",root,Map.of(),Map.of(),null));assertThrows(BffFailure.class,()->KnowledgeWire.route("DELETE",root));assertThrows(BffFailure.class,()->KnowledgeWire.route("GET",root+"/11111111-1111-1111-1111-zzzzzzzzzzzz"));assertThrows(BffFailure.class,()->wire.request("PATCH",root+"/"+id,Map.of(),map("expectedRevision",9007199254740992L,"metadata",map("title","x","description","")),"key"));assertFalse(wire.validate("unknown",Map.of()));}
 @Test void callerCancellationCannotRenewOwner(){var deadline=new KnowledgeDeadline();assertTrue(deadline.remainingNanos()>0);deadline.cancel();assertThrows(BffFailure.class,deadline::check);assertThrows(BffFailure.class,deadline::remainingNanos);}
}
